(function () {
  "use strict";

  function decode(value) {
    var key = parseInt(value.slice(0, 2), 16);
    var output = "";

    for (var i = 2; i < value.length; i += 2) {
      output += String.fromCharCode(parseInt(value.slice(i, i + 2), 16) ^ key);
    }

    return output;
  }

  function restore(link) {
    var encoded = link.getAttribute("data-cfemail");

    if (!encoded) {
      var hashIndex = link.href.indexOf("#");
      encoded = hashIndex >= 0 ? link.href.slice(hashIndex + 1) : "";
    }

    if (!encoded) return;

    var email = decode(encoded);
    link.textContent = email;
    link.href = "mailto:" + email;
    link.classList.remove("__cf_email__");
  }

  document.querySelectorAll(".__cf_email__, a[href*='/cdn-cgi/l/email-protection']").forEach(restore);
})();
